  57 /// An npm package whose `package.json` declares both `os` and `cpu` constraints
  58 /// is a napi platform package and must appear in `npm_platform_packages`, not
  59 /// in `npm_main_packages`. Before the walk.rs fix, `ManifestRole::Platform` was
  60 /// never assigned so every npm package landed in `npm_main_packages`.
  61 #[test]
  62 fn napi_platform_package_is_classified_as_npm_platform_packages() {
  63     use callisto_graph::commands::{plan_publish, PublishOptions};
  64 
  65     let tmp = tempfile::tempdir().unwrap();
  66     let root = tmp.path();
  67 
  68     // A napi platform package: declares os and cpu constraints.
  69     std::fs::write(
  70         root.join("package.json"),
  71         r#"{"name":"@scope/my-lib-linux-x64-gnu","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
  72     )
  73     .unwrap();
