 501 // ---- Git discovery failure emits diagnostic ----------------------------------
 502 
 503 /// When `plan_publish` cannot resolve a HEAD SHA (because the workspace is not
 504 /// inside a git repository, or because the git repo has no commits), the
 505 /// `releases` list in the resulting plan will be empty. Previously this was
 506 /// silent — the operator had no indication why no release entries appeared.
 507 ///
 508 /// The fix: emit a `GitDiscoveryFailed` diagnostic with `severity: warning` so
 509 /// the operator can see what went wrong while still receiving a usable plan.
 510 #[test]
 511 fn non_git_workspace_emits_git_diagnostic() {
 512     use callisto_graph::commands::{plan_publish, PublishOptions};
 513     use callisto_model::DiagnosticCode;
 514 
 515     let tmp = tempfile::tempdir().unwrap();
 516     let root = tmp.path();
 517 
 518     // An npm package so the plan has something to work with — but deliberately
 519     // NO git init, so git discovery fails.
 520     std::fs::write(root.join("package.json"), r#"{"name":"my-pkg","version":"1.0.0"}"#).unwrap();
